	sections = {
		{
			title = "Summary",
			text = [=[The Gadgetzan Water Company keeps the wells and pumps of {link:gadgetzan}Gadgetzan{/link}, and in a desert that makes it the most important business in {link:tanaris}Tanaris{/link}. Its engineers dig the water holes, its spigot operators run the tower, and its surveyors search the sands for new springs. It sells water, as it sells everything, at a price.]=],
		},
		{
			title = "In These Days",
			text = [=[The company is at war. The {link:wastewander-nomads}Wastewander nomads{/link} have seized nearly all its wells beyond the walls, murdered its workers and stolen its stores. {link:chief-engineer-bilgewhizzle}Chief Engineer Bilgewhizzle{/link} has posted bounties on the nomads and on their leader, {link:caliph-scorpidsting}Caliph Scorpidsting{/link}, and Spigot Operator Luglunket pays for every water pouch taken back from them. Meanwhile, {link:senior-surveyor-fizzledowser}Senior Surveyor Fizzledowser{/link} sends junior surveyors out to find new water, and they have found worse than nomads. Insects are draining the free pools of the west, and one of the company's surveyors has already died in the {link:the-gaping-chasm}Gaping Chasm{/link}. The company, which usually sells what it learns, has chosen to give its report on the insects away to anyone who will read it.]=],
		},
		{
			title = "Structure",
			text = [=[• {b}{link:chief-engineer-bilgewhizzle}Chief Engineer Bilgewhizzle{/link}{/b} leads the company's fight for its wells.
• {b}{link:senior-surveyor-fizzledowser}Senior Surveyor Fizzledowser{/link}{/b} leads the survey of new water.
• {b}Spigot Operator Luglunket{/b} keeps the water tower and its bounties.
• {b}{link:security-chief-bilgewhizzle}Security Chief Bilgewhizzle{/link}{/b} of {link:steamwheedle-port}Steamwheedle Port{/link} bears the title of Water Co. Security.]=],
		},
	},
})

