			text = [=[The Sandfury are the trolls of the desert. Their city is {red:zul-farrak}Zul'Farrak{/red}, in the north-west of {link:tanaris}Tanaris{/link}, and their warriors keep watch from outposts such as {link:sandsorrow-watch}Sandsorrow Watch{/link}. They are known for cruelty, and for a dark mysticism that raises their dead to serve them. They worship Gahz'rilla, a great hydra that they summon from a sacred pool in the heart of their city.]=],
		},
		{
			title = "Their Crafts",
			text = [=[The Sandfury make a tempering agent from the desert's sandstone, prized by smiths who know good metal. Scarabs swarm in their city, where no troll hunts them for their shells. Old tablets of the prophet Mosh'aru, taken there long ago, are kept by their priests.]=],
		},
		{
			title = "In These Days",
			text = [=[The Sandfury have no friends in the desert. Goblin smiths and scholars pay for what can be taken from their city, and bands of treasure hunters go in after its riches. Not all of them come out.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of these days tells how long the Sandfury have held Zul'Farrak, or what bond they keep with the other troll tribes.]=],
		},
	},
})

Add({
