	unlock = {
		{ type = "interact" },
	},
	hint = "Seek the goblin who governs Gadgetzan.",
	sections = {
		{
			title = "Summary",
			text = [=[Marin Noggenfogger is the goblin master of {link:gadgetzan}Gadgetzan{/link}, the town that the {link:steamwheedle-cartel}Steamwheedle Cartel{/link} raised in the desert of {link:tanaris}Tanaris{/link}. Where {link:baron-revilgaz}Baron Revilgaz{/link} rules {link:booty-bay}Booty Bay{/link} and {link:gazlowe}Gazlowe{/link} watches over {link:ratchet}Ratchet{/link}, Noggenfogger holds the Cartel's desert town. He is restless, thirsty and always hunting for the next great idea. Even his friends call him eccentric.]=],
		},
		{
			title = "Significance",
			text = [=[{link:gadgetzan}Gadgetzan{/link} sits on the only safe water for many leagues, and its master rules at the crossing of every road in the south. Under Noggenfogger the town has stayed neutral ground. {link:alliance}Alliance{/link} and {link:horde}Horde{/link} alike rest behind its walls, and the bruisers of the town keep the peace. His name is also known far beyond the desert for the elixir that bears it, which he means to make his fortune.]=],
		},
		{
			title = "Deeds",
			text = [=[• He governs {link:gadgetzan}Gadgetzan{/link} for the {link:steamwheedle-cartel}Steamwheedle Cartel{/link}.
• He heard of strange desert creatures that store water in their glands, and set out to brew a drink from them.
• With the help of his friend {link:sprinkle}Sprinkle{/link}, he created the Noggenfogger Elixir.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells how Noggenfogger came to rule {link:gadgetzan}Gadgetzan{/link}, or who ruled it before him.]=],
