			title = "The Thirsty Goblin",
			hint = [=[Bring the thirsty master of Gadgetzan what the cactus garden hides.]=],
			unlock = {
				{ type = "quest", id = 2605 },
			},
			text = [=[Noggenfogger's thirst was so great that he grew desperate. He had heard of the dew collectors of {link:thistleshrub-valley}Thistleshrub Valley{/link}, and he reasoned that the water in their glands might finally quench it. When a laden gland was brought to him, he drank it at once. It tasted terrible. He nearly gave up, until he decided that a drink that bad ought at least to have some kick.]=],
		},
		{
			key = "the-elixir",
			title = "The Elixir",
			hint = "Help the goblin perfect his drink.",
			unlock = {
				{ type = "quest", id = 2662 },
			},
			text = [=[{link:sprinkle}Sprinkle{/link}, the cook of {link:gadgetzan}Gadgetzan{/link}, knew a secret: a violet mushroom that grows under the water of a small lake in the {link:the-hinterlands}Hinterlands{/link}. Ground to powder and mixed with the dew, it made the brew not only drinkable but wonderful. Noggenfogger declared that he would make millions from it. When he heard that he owed Sprinkle a favor, he called her a great kidder.]=],
