Add({
	kind = "figure",
	id = "yeh-kinya",
	title = "Yeh'kinya",
	subtitle = "Scholar of the Troll Prophecies",
	tier = "B",
	region = "tanaris",
	npc = { 8579 },
	allegiance = "Unknown",
	found = "Steamwheedle Port",
	pin = { x = 67.0, y = 22.4 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the troll who studies old prophecies among the crates of Steamwheedle Port.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Yeh'kinya is a troll who lives among the goblins of {link:steamwheedle-port}Steamwheedle Port{/link}. He knows the old legends of his people better than most, and above all the legend of {link:hakkar}Hakkar{/link} the Soulflayer, the dead god of blood. He says that he does not believe the tales of Hakkar's return. He does believe that the essence of the god holds great power, and he has set out to gather it.]=],
		},
		{
			title = "Significance",
			text = [=[Yeh'kinya is the one who set the Egg of {link:hakkar}Hakkar{/link} in motion. Through the spirits of beasts, the tablets of a dead prophet and an egg hidden in a troll city, he learned how the essence of the Soulflayer might be caught and held. He speaks of keeping it from those who would abuse it. Not everyone believes him.]=],
		},
		{
			title = "Deeds",
			text = [=[• He sought the spirits of the vale screechers of {link:feralas}Feralas{/link}, which he calls cousins of an old god.
• He gathered the first two tablets of the prophet Mosh'aru from {red:zul-farrak}Zul'Farrak{/red} and fused them together.
• He sent for an ancient egg from {link:jintha-alor}Jintha'Alor{/link}, a relic of the troll empires.
• He sent the egg into the {link:temple-of-atal-hakkar}Temple of Atal'Hakkar{/link}, where the essence of the god was captured.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells which tribe Yeh'kinya comes from, or why he lives among goblins.]=],
		},
	},
	chapters = {
		{
			key = "screecher-spirits",
			title = "Screecher Spirits",
			hint = [=[Bring the troll of Steamwheedle Port the spirits of the Feralas screechers.]=],
			unlock = {
				{ type = "quest", id = 3520 },
			},
			text = [=[Yeh'kinya wanted the spirits of the vale screechers, for he held that they were linked to an ancient god. When they were brought to him, he told of an old troll prophecy: that the dead god {link:hakkar}Hakkar{/link} would one day return to the world. Some trolls say this will bring glory. Others say it will bring the end of all things.]=],
		},
		{
			key = "the-prophecy-of-mosh-aru",
			title = "The Prophecy of Mosh'aru",
			hint = "Bring the troll the tablets of the prophet from Zul'Farrak.",
			unlock = {
				{ type = "quest", id = 3527 },
			},
			text = [=[The prophecy of Mosh'aru was written on two tablets and carried to Zul'Farrak. One was held by the dead troll Theka the Martyr, the other by the hydromancer Velratha beside the sacred pool. Yeh'kinya fused the tablets and read their secret: an ancient egg could hold the essence of {link:hakkar}Hakkar{/link}.]=],
		},
		{
			key = "the-egg-of-hakkar",
			title = "The Egg of Hakkar",
			hint = [=[Carry the egg into the drowned temple and bring it back full.]=],
			unlock = {
				{ type = "quest", id = 3528 },
			},
			text = [=[The egg was found in {link:jintha-alor}Jintha'Alor{/link} and carried into the Sanctum of the Fallen God. The avatar of {link:hakkar}Hakkar{/link} came forth and fell, and its essence was sealed in the egg. When the egg came back to {link:tanaris}Tanaris{/link}, it stirred with life. Yeh'kinya seemed shaken, and he swore to keep it safe from evil hands.]=],
		},
		{
			key = "the-lost-tablets",
			title = "The Lost Tablets",
			hint = "Hear what the dwarf of Steamwheedle Port has learned.",
			unlock = {
				{ type = "quest", id = 5065 },
			},
			text = [=[A {link:dwarves}dwarf{/link} prospector who stands a few steps from Yeh'kinya has studied the prophecy too. He says that there are six tablets of Mosh'aru, not two, and that the troll did not tell the whole truth.]=],
		},
	},
	mentions = {
		{
			text = "The Ancient Egg",
			unlock = {
				{ type = "quest", id = 4787 },
			},
		},
	},
	bonds = {
		{ id = "hakkar", name = "Hakkar", note = "the god whose essence he gathers" },
		{ id = "avatar-of-hakkar", name = "Avatar of Hakkar", note = "whose essence fills his egg" },
		{ id = "prospector-ironboot", name = "Prospector Ironboot", note = "doubts his word" },
	},
})

Add({
	kind = "figure",
	id = "senior-surveyor-fizzledowser",
	title = "Senior Surveyor Fizzledowser",
	aliases = { "Fizzledowser" },
	subtitle = "Gadgetzan Water Co.",
	tier = "B",
	region = "tanaris",
	npc = { 7724 },
	allegiance = "Gadgetzan Water Company · Gadgetzan",
	found = "Gadgetzan, at the western side of the town",
	pin = { x = 50.2, y = 27.5 },
	unlock = {
		{ type = "interact" },
	},
	hint = "Seek the goblin who surveys the desert for new water.",
	sections = {
		{
			title = "Summary",
			text = [=[Senior Surveyor Fizzledowser leads the search for water in the desert for the {link:gadgetzan-water-company}Gadgetzan Water Company{/link}. With {link:wastewander-nomads}the nomads{/link} holding the wells, he sends junior surveyors out into the sand with dowsing widgets to find free pools and springs. What they have found is a threat far greater than any nomad.]=],
		},
		{
			title = "Significance",
			text = [=[Fizzledowser is the goblin who first raised the alarm about the insects of {link:tanaris}Tanaris{/link}. At first he dismissed the reports of strange bug creatures sucking up water as another trick of {link:wastewander-nomads}the nomads{/link}. Then his surveyors began to die. His reports, and those of {link:alchemist-pestlezugg}Alchemist Pestlezugg{/link}, have carried the name of the {link:qiraji}silithid{/link} from {link:gadgetzan}Gadgetzan{/link} to {link:orgrimmar}Orgrimmar{/link} and {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He sent a surveyor to test the pool near {link:sandsorrow-watch}Sandsorrow Watch{/link}, where the first insect attack came.
• He ordered parts gathered from the insects of the {link:the-noxious-lair}Noxious Lair{/link} for study.
• He lost his top assistant, Junior Surveyor Scrimshank, in the {link:the-gaping-chasm}Gaping Chasm{/link}.
• He agreed to share the insect report freely, against every habit of his trade.]=],
		},
	},
	chapters = {
		{
			key = "the-water-survey",
			title = "The Water Survey",
			hint = [=[Tap the pool near the troll watchtower for the Water Company.]=],
			unlock = {
				{ type = "quest", id = 992 },
			},
			text = [=[The surveyor who went to the pool at {link:sandsorrow-watch}Sandsorrow Watch{/link} was ambushed by a creature out of the sand. Fizzledowser admitted that he had heard of such creatures. He had not believed it. Now he did, and he feared what it meant for the company.]=],
		},
		{
			key = "the-scrimshank-redemption",
			title = "The Scrimshank Redemption",
			hint = [=[Discover what became of the surveyor lost in the Gaping Chasm.]=],
			unlock = {
				{ type = "quest", id = 10 },
			},
			text = [=[Scrimshank had gone into the {link:the-gaping-chasm}Gaping Chasm{/link}, and his last report spoke of more insects there. Only his surveying equipment came back. Fizzledowser put the young goblin's effects in order himself. The records that Scrimshank left suggested that the insects might be under the control of some third power.]=],
		},
		{
			key = "rise-of-the-silithid",
			title = "Rise of the Silithid",
			hint = [=[Carry the report on the insects to the scholars of the great cities.]=],
			unlock = {
				{ type = "quest", id = 113 },
				{ type = "quest", id = 32 },
				{ type = "quest", id = 162 },
			},
			text = [=[{link:alchemist-pestlezugg}Pestlezugg{/link} asked that everyone who could read should see the report. Fizzledowser, who usually sold knowledge for good coin, made copies and sent them to the scholars he knew in the capitals. From them came the name of the enemy.]=],
		},
	},
	mentions = {
		{
			text = "{link:the-noxious-lair}Noxious Lair{/link} Investigation",
			unlock = {
				{ type = "quest", id = 82 },
			},
		},
		{
			text = "Insect Part Analysis",
			unlock = {
				{ type = "quest", id = 110 },
			},
		},
	},
	bonds = {
		{ id = "alchemist-pestlezugg", name = "Alchemist Pestlezugg", note = "studies the insects with him" },
		{ id = "chief-engineer-bilgewhizzle", name = "Chief Engineer Bilgewhizzle", note = "fellow officer of the Water Company" },
	},
})

